use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use rusoto_s3::{S3Client, S3, PutObjectRequest};
use rusoto_core::Region;

#[derive(Deserialize, Serialize, Clone, Debug)]
pub struct UserProfile {
    pub username: String,
    pub email: String,
    pub display_name: String,
    // Internal fields that should not be user-settable
    pub role: Option<String>,           // "admin", "user", "moderator"
    pub account_tier: Option<String>,   // "free", "premium", "enterprise"
    pub s3_export_prefix: Option<String>, // controls where profile exports land in S3
    pub internal_flags: Option<u64>,
}

#[derive(Deserialize, Serialize, Clone, Debug)]
pub struct StoredProfile {
    pub username: String,
    pub email: String,
    pub display_name: String,
    pub role: String,
    pub account_tier: String,
    pub s3_export_prefix: String,
    pub internal_flags: u64,
}

impl From<UserProfile> for StoredProfile {
    fn from(p: UserProfile) -> Self {
        StoredProfile {
            username: p.username,
            email: p.email,
            display_name: p.display_name,
            // Mass assignment: user-supplied values override defaults
            role: p.role.unwrap_or_else(|| "user".to_string()),
            account_tier: p.account_tier.unwrap_or_else(|| "free".to_string()),
            s3_export_prefix: p.s3_export_prefix.unwrap_or_else(|| "exports/default/".to_string()),
            internal_flags: p.internal_flags.unwrap_or(0),
        }
    }
}

async fn update_profile(
    profile: web::Json<UserProfile>,
    s3_client: web::Data<S3Client>,
) -> HttpResponse {
    let stored: StoredProfile = profile.into_inner().into();

    // Export profile to S3 using user-controlled prefix
    let key = format!("{}{}.json", stored.s3_export_prefix, stored.username);
    let body = serde_json::to_vec(&stored).unwrap_or_default();

    let put_req = PutObjectRequest {
        bucket: std::env::var("PROFILE_BUCKET").unwrap_or_else(|_| "app-profiles-prod".into()),
        key: key.clone(),
        body: Some(body.into()),
        content_type: Some("application/json".to_string()),
        ..Default::default()
    };

    match s3_client.put_object(put_req).await {
        Ok(_) => HttpResponse::Ok().json(serde_json::json!({
            "status": "updated",
            "profile": stored,
            "export_path": key
        })),
        Err(e) => HttpResponse::InternalServerError().json(serde_json::json!({
            "error": format!("Failed to export profile: {}", e)
        })),
    }
}

async fn get_profile(path: web::Path<String>) -> HttpResponse {
    // Stub: would read from database
    HttpResponse::Ok().json(serde_json::json!({"username": path.into_inner()}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let region = Region::Custom {
        name: "us-east-1".to_string(),
        endpoint: std::env::var("AWS_ENDPOINT").unwrap_or_else(|_| "https://s3.us-east-1.amazonaws.com".into()),
    };
    let s3_client = S3Client::new(region);

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(s3_client.clone()))
            .route("/api/profile", web::post().to(update_profile))
            .route("/api/profile/{username}", web::get().to(get_profile))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
